export const ALL_ROLES = 'ALL';

export const usersFilterSchema = z.object({
  search: z.string(),
  role: z.union([z.literal(ALL_ROLES), z.nativeEnum(ROLES)]),
});

export type UsersFilter = z.infer<typeof usersFilterSchema>;

export const filterUsers = (users: User[], { search, role }: UsersFilter) => {
  const term = search.trim().toLowerCase();

  return users.filter((user) => {
    if (role !== ALL_ROLES && user.role !== role) return false;
    if (!term) return true;

    const name = `${user.firstName} ${user.lastName}`.toLowerCase();
    return name.includes(term) || user.email.toLowerCase().includes(term);
  });
};
"""
open(p,'w').write(s)
